import { useState } from "react";
import { Check } from "lucide-react";
import { cn } from "@/lib/cn";
import { useAnnounce } from "./announce";

// The one control that records a dish as cooked. 48 px circle, icon only.
// Name flips "Mark {dish} cooked" / "Unmark {dish} cooked"; no aria-pressed (the state would be said twice).
// The tick announces itself through the shared region. The consumer renders it only where it applies (absent, not disabled).

export type CookedTickProps = {
  /** Dish name, inserted verbatim into the name and the announcement. */
  dish: string;
  cooked?: boolean;
  defaultCooked?: boolean;
  onCookedChange?: (cooked: boolean) => void;
  /** Wording, for translated builds. */
  labels?: { mark: (dish: string) => string; unmark: (dish: string) => string; marked: (dish: string) => string; unmarked: (dish: string) => string };
  className?: string;
};

const english = {
  mark: (d: string) => `Mark ${d} cooked`,
  unmark: (d: string) => `Unmark ${d} cooked`,
  marked: (d: string) => `${d} marked cooked`,
  unmarked: (d: string) => `${d} unmarked`,
};

export function CookedTick({ dish, cooked, defaultCooked = false, onCookedChange, labels = english, className }: CookedTickProps) {
  const [inner, setInner] = useState(defaultCooked);
  const set = cooked ?? inner;
  const say = useAnnounce();
  return (
    <button
      type="button"
      aria-label={set ? labels.unmark(dish) : labels.mark(dish)}
      onClick={() => {
        const next = !set;
        setInner(next);
        onCookedChange?.(next);
        say(next ? labels.marked(dish) : labels.unmarked(dish));
      }}
      className={cn(
        "inline-flex size-icon-target shrink-0 items-center justify-center rounded-pill border-bw-strong transition-colors duration-fast ease-standard",
        "focus-visible:outline focus-visible:outline-ring focus-visible:outline-offset-ring focus-visible:outline-focus-ring",
        set
          ? "border-transparent bg-primary text-primary-on hover:bg-primary-hover active:bg-primary-active"
          : "border-border-strong bg-surface-raised text-border-strong hover:bg-surface-sunken active:border-text active:bg-surface-sunken",
        className,
      )}
    >
      <Check aria-hidden="true" className="size-icon-lg" />
    </button>
  );
}
